// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(amount > 0);

        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;

        vm.prank(caller);
        c.withdraw(amount);

        uint256 balanceAfter = address(c).balance;
        assertEq(balanceBefore - balanceAfter, amount);
    }
}
